property.value:
let $plus := function($node) { exists($node/self::InfixExpression[@Operator = '+']) },
    $leaves := function($expression) {
  if ($plus($expression))
  then $expression/descendant::*[not($plus(.))][parent::InfixExpression[@Operator = '+']]
         [ancestor::*[not($plus(.))][1] is $expression/parent::*]
  else $expression
},
    $initial := function($access) {
  ($access/ancestor::*[self::MethodDeclaration or self::ConstructorDeclaration][1]
     //VariableDeclarator[VariableId/@Name = $access/@Name],
   $access/ancestor::CompilationUnit//FieldDeclaration/VariableDeclarator[VariableId/@Name = $access/@Name])[1]/*[2]
},
    $literal := function($leaf) {
  if ($leaf/self::StringLiteral) then string($leaf/@ConstValue)
  else if ($leaf/self::NumericLiteral) then string($leaf/@Image)
  else '&#xa4;'
},
    $text0 := function($expression) { string-join(for $leaf in $leaves($expression) return $literal($leaf), '') },
    $text1 := function($expression) {
  string-join(for $leaf in $leaves($expression)
              return if ($leaf/self::VariableAccess and exists($initial($leaf))) then $text0($initial($leaf))
                     else $literal($leaf), '')
},
    $text := function($expression) {
  string-join(for $leaf in $leaves($expression)
              return if ($leaf/self::VariableAccess and exists($initial($leaf))) then $text1($initial($leaf))
                     else $literal($leaf), '')
},
    $dynamic := function($text) { contains($text, '&#xa4;') },
    $ordered := function($text) { matches($text, '(^|\W)order\s+by\s', 'i') },
    $countOrConstant := function($text) {
  matches($text, '^\s*select\s+((count|max|min|sum|avg|exists)\s*\(|(1|true)(\s|$))', 'i')
},
    $unorderedSql := function($text) {
  matches($text, '^\s*\(?\s*(select\s|with\s+(recursive\s+)?\w+(\s*\([^)]*\))?\s+as\s*\()', 'i')
  and not($dynamic($text)) and not($ordered($text))
  and ((matches($text, '(^|\W)from\s', 'i')
        and matches($text, '(^|[^\w:.])(limit|offset)\s+(\d|\?|:\w|\$\d|%s)|(^|\W)fetch\s+(first|next)\s', 'i')
        and not($countOrConstant($text)
                and matches($text, '(^|\W)limit\s+1(\W|$)|(^|\W)fetch\s+first\s+(1\s+)?rows?\s+only', 'i')
                and not(matches($text, '(^|\W)offset(\W|$)', 'i'))))
       or matches($text, '(^|\W)(array_agg|jsonb?_agg)\s*\(', 'i'))
},
    $creators := ('createQuery', 'createNativeQuery'),
    $created := function($call) {
  let $receiver := $call/*[1],
      $held := ($receiver/descendant-or-self::VariableAccess)[1]
  return ($receiver/descendant-or-self::MethodCall[@MethodName = $creators],
          $initial($held)/descendant-or-self::MethodCall[@MethodName = $creators])[1]
},
    $unorderedPage := function($call) {
  let $query := $created($call),
      $argument := $query/ArgumentList/*[1],
      $text := $text($argument),
      $criteria := $argument/self::VariableAccess[exists($initial(.)/self::MethodCall[@MethodName = 'createQuery'][ArgumentList/ClassLiteral])],
      $single := $call/@MethodName = 'setMaxResults' and $call/ArgumentList/NumericLiteral/@Image = '1'
  return exists($query)
    and not($call/@MethodName = 'setFirstResult' and $call/ArgumentList/NumericLiteral/@Image = '0')
    and (if (not($dynamic($text))) then not($ordered($text)) and not($single and $countOrConstant($text))
         else exists($criteria)
              and not($call/ancestor::*[self::MethodDeclaration or self::ConstructorDeclaration][1]
                       //MethodCall[@MethodName = 'orderBy'][*[1][self::VariableAccess/@Name = $argument/@Name]]))
},
    $toFindAll := function($page) {
  exists($page/parent::ArgumentList/parent::MethodCall[@MethodName = 'findAll'])
  or (let $name := $page/parent::VariableDeclarator/VariableId/@Name
      return exists($page/ancestor::MethodDeclaration[1]//MethodCall[@MethodName = 'findAll']/ArgumentList/VariableAccess[@Name = $name]))
}
return (
  //StringLiteral[not(parent::InfixExpression[@Operator = '+'])][$unorderedSql(string(@ConstValue))]
  | //InfixExpression[@Operator = '+'][not(parent::InfixExpression[@Operator = '+'])][descendant::StringLiteral]
      [$unorderedSql($text(.))]
  | //MethodCall[@MethodName = ('setMaxResults', 'setFirstResult')][$unorderedPage(.)]/ArgumentList
  | //MethodCall[@MethodName = 'of'][count(ArgumentList/*) = 2]
      [*[1][self::TypeExpression/ClassType[@SimpleName = 'PageRequest']]][$toFindAll(.)]
  | //MethodCall[@MethodName = 'ofSize']
      [*[1][self::TypeExpression/ClassType[@SimpleName = ('PageRequest', 'Pageable')]]][$toFindAll(.)]
)
